    Spinner select(LinearLayout parent,String label,String[] values,String selected){parent.addView(text(label,12,palette.muted,false));Spinner s=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values){@Override public View getView(int p,View c,android.view.ViewGroup g){TextView t=(TextView)super.getView(p,c,g);t.setTextColor(palette.text);t.setTextSize(14);return t;}};s.setAdapter(a);s.setMinimumHeight(dp(48));s.setBackground(shape(palette.surface,10));s.setContentDescription(label);for(int i=0;i<values.length;i++)if(values[i].equals(selected))s.setSelection(i);parent.addView(s,new LinearLayout.LayoutParams(-1,-2));space(parent,12);return s;}
