        nav=row();nav.setPadding(dp(6),dp(6),dp(6),dp(6));String[] labels={"Home","Release","Beats","Studio","More"};for(String label:labels){TextView t=text(label,11,palette.muted,true);t.setGravity(Gravity.CENTER);t.setMinHeight(dp(52));t.setContentDescription(label);t.setOnClickListener(v->{switch(label){case "Home":home();break;case "Release":releases();break;case "Beats":desk.beats();break;case "Studio":desk.studio();break;default:more();}});nav.addView(t,new LinearLayout.LayoutParams(0,-2,1));}root.addView(nav);
