    String initials(){return session.optJSONObject("user")==null?"You":session.optJSONObject("user").optString("name","You").concat("Y").substring(0,1).toUpperCase(Locale.ROOT);}
    void page(String key,String title,String subtitle){screen=key;epoch++;body.setGravity(key.equals("signin")?Gravity.CENTER_VERTICAL:Gravity.TOP);header.setVisibility(key.equals("signin")?View.GONE:View.VISIBLE);nav.setVisibility(key.equals("signin")?View.GONE:View.VISIBLE);body.removeAllViews();scroll.scrollTo(0,0);progress.setVisibility(View.GONE);if(!title.isEmpty()){body.addView(text(title,28,palette.text,true));space(body,6);body.addView(text(subtitle,13,palette.muted,false));space(body,22);}}
    interface Work {JSONObject run()throws Exception;}
    void task(Work work,java.util.function.Consumer<JSONObject> done){int current=epoch;progress.setVisibility(View.VISIBLE);workers.execute(()->{try{JSONObject result=work.run();runOnUiThread(()->{if(current!=epoch||isFinishing())return;progress.setVisibility(View.GONE);done.accept(result);});}catch(Exception e){runOnUiThread(()->{if(current!=epoch||isFinishing())return;progress.setVisibility(View.GONE);boolean wasAuth=authBusy;authBusy=false;if(wasAuth&&screen.equals("signin"))signIn();if(e instanceof CustomerApi.Failure&&((CustomerApi.Failure)e).status==401&&!screen.equals("signin")){api.clearSession();signIn();}else error(e.getMessage());});}});}
    void get(String path,java.util.function.Consumer<JSONObject> done){task(()->api.request("GET",path,null),done);}
    void post(String path,JSONObject data,java.util.function.Consumer<JSONObject> done){task(()->api.request("POST",path,data),done);}
    void error(String message){new AlertDialog.Builder(this).setTitle("Needs attention").setMessage(message==null?"Please try again.":message).setPositiveButton("OK",null).show();}
    void notice(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
    boolean signed(){if(api.signedIn())return true;signIn();return false;}
    void restore(){get("/api/customer-app/session",data->{session=data;shell();home();JSONObject app=data.optJSONObject("app");if(app!=null&&app.optInt("latestVersionCode")>BuildConfig.VERSION_CODE)new AlertDialog.Builder(this).setTitle("A new HYMN is ready").setMessage("Update to get the latest features and fixes. Your account stays the same.").setNegativeButton("Later",null).setPositiveButton("Get update",(d,w)->external(CustomerApi.BASE+"/music/app/download")).show();});}
    void signIn(){page("signin","Your music.\nOne HYMN account.","Sign in or create your account with email.");LinearLayout form=card(body);ImageView signInLogo=new ImageView(this);signInLogo.setImageResource(R.drawable.hymn_logo);signInLogo.setContentDescription("HYMN Music");LinearLayout.LayoutParams logoSize=new LinearLayout.LayoutParams(dp(48),dp(48));logoSize.gravity=Gravity.CENTER_HORIZONTAL;logoSize.bottomMargin=dp(20);form.addView(signInLogo,logoSize);EditText address=field(form,"Email address",email,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);EditText name=challenge.isEmpty()?field(form,"Your name (for a new account)","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS):null;
        if(!challenge.isEmpty()){address.setEnabled(false);EditText code=field(form,"Six-digit code","",InputType.TYPE_CLASS_NUMBER);code.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(6)});form.addView(button("Verify & continue",()->{if(authBusy)return;if(code.getText().length()!=6){code.setError("Enter six digits");return;}authBusy=true;authLoading();post("/api/auth/email",json("action","verify","email",email,"challenge",challenge,"code",code.getText().toString()),data->{authBusy=false;challenge="";restore();});}));space(form,8);form.addView(secondary("Change email",()->{challenge="";signIn();}));space(form,8);TextView resend=secondary("Resend code",()->{if(System.currentTimeMillis()<resendAt){notice("Please wait before requesting another code.");return;}requestCode(address.getText().toString(),"");});form.addView(resend);
        }else form.addView(button("Send me a code",()->requestCode(address.getText().toString(),name.getText().toString())));
        space(form,12);form.addView(text("Use the most recent code. It expires in 10 minutes and can be used once.",11,palette.muted,false));}
    void authLoading(){body.removeAllViews();body.setGravity(Gravity.CENTER);LinearLayout box=card(body);box.setGravity(Gravity.CENTER);box.setPadding(dp(24),dp(44),dp(24),dp(44));FrameLayout circle=new FrameLayout(this);ProgressBar spinner=new ProgressBar(this);circle.addView(spinner,new FrameLayout.LayoutParams(dp(112),dp(112),Gravity.CENTER));ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.hymn_logo);circle.addView(logo,new FrameLayout.LayoutParams(dp(48),dp(48),Gravity.CENTER));box.addView(circle,new LinearLayout.LayoutParams(-1,dp(140)));space(box,16);box.addView(text(challenge.isEmpty()?"Sending your secure code…":"Opening your HYMN…",13,palette.muted,false));}
    void requestCode(String address,String name){address=address.trim().toLowerCase(Locale.ROOT);if(!android.util.Patterns.EMAIL_ADDRESS.matcher(address).matches()){error("Enter a valid email address.");return;}if(authBusy)return;authBusy=true;email=address;authLoading();post("/api/auth/email",json("action","request","email",email,"name",name),data->{authBusy=false;challenge=data.optString("challenge");resendAt=System.currentTimeMillis()+data.optLong("resendAfter",60)*1000;signIn();});}
    void home(){page("home","Your next move\nstarts here.","Release. Create. Get heard.");LinearLayout hero=card(body);hero.addView(text("MADE FOR YOUR MUSIC",10,palette.muted,true));space(hero,10);hero.addView(text("Independent sound.\nWorldwide possibilities.",23,palette.text,true));space(hero,16);hero.addView(button("Start a release",()->{if(signed())distribution.start();}));tile("Beat Store","Find the sound for your next track",()->desk.beats());tile("Mixing & mastering","Work with verified engineers",()->desk.studio());tile("Playlist curation","Listening and honest feedback",()->desk.playlists());if(api.signedIn()){tile("Your releases","Drafts, corrections and store status",()->releases());if(!api.saved("pending-payment").isEmpty())tile("Payment confirmation","Resume verification without paying again",()->retryPayment());}else tile("Your HYMN account","Sign in or create an account with email",()->signIn());}
    void tile(String title,String subtitle,Runnable click){LinearLayout c=card(body);c.addView(text(title+"  ›",17,palette.text,true));space(c,5);c.addView(text(subtitle,12,palette.muted,false));c.setMinimumHeight(dp(84));c.setOnClickListener(v->click.run());c.setContentDescription(title);}
    void releases(){if(!signed())return;page("releases","Your releases","Your catalogue, from first draft to live stores.");body.addView(button("Create release",()->distribution.start()));space(body,16);get("/api/distribution/my-releases",data->{JSONArray list=data.optJSONArray("releases");if(list==null||list.length()==0)empty("Your next release starts here.");else for(int i=0;i<list.length();i++){JSONObject release=list.optJSONObject(i);if(release!=null)tile(release.optString("releaseTitle",release.optString("trackName","Untitled")),release.optString("artistName")+" · "+release.optString("status"),()->distribution.open(release));}});}
    void empty(String message){LinearLayout c=card(body);c.addView(text(message,14,palette.muted,false));}
    void more(){page("more","Your workspace","Everything you need, with room to breathe.");tile("Playlist curation","Find curators and track your reviews",()->desk.playlists());tile("My purchases","Beat downloads and licences",()->desk.purchases());tile("Artist profiles","Create and manage your artists",()->desk.artists());tile("Plans & subscriptions","Your distribution plan and artist slots",()->desk.plans());tile("Audio library","Your private uploaded audio",()->desk.library());tile("Referrals","Your link, circle, earnings and payouts",()->desk.referrals());tile("Earnings & payouts","Balances, reports and verified payout details",()->desk.payouts());tile("Notifications","Updates on your music and account",()->desk.notifications());tile("Help & support","Ask HYMN and track your tickets",()->desk.support());tile("Profile & preferences","Personal details, appearance and sign out",()->desk.account());}
    void chooseFile(String type,java.util.function.Consumer<Uri> result){pickedFile=result;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(type).addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(intent,101);}catch(Exception e){pickedFile=null;error("No file picker is available on this device.");}}
    void saveDownload(String path,String filename,String mime){pendingDownload=path;pendingDownloadName=filename;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(mime).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,filename);try{startActivityForResult(intent,102);}catch(Exception e){error("No document provider is available.");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==101){java.util.function.Consumer<Uri> callback=pickedFile;pickedFile=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&callback!=null)callback.accept(data.getData());}else if(request==102&&result==RESULT_OK&&data!=null){Uri uri=data.getData();String path=pendingDownload;task(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){api.download(path,out);}return json("saved",true);},o->notice("Saved to your selected location."));}}
    void play(String path){try{if(!path.startsWith("/")&&!path.startsWith("https://"))throw new Exception();if(player!=null){player.release();player=null;}player=new android.media.MediaPlayer();android.media.AudioAttributes attrs=new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_MEDIA).setContentType(android.media.AudioAttributes.CONTENT_TYPE_MUSIC).build();player.setAudioAttributes(attrs);String url=path.startsWith("/")?CustomerApi.BASE+path:path;Map<String,String> headers=new HashMap<>();if(MusicNavigation.internal(url))headers.put("Cookie",api.saved("cookie"));player.setDataSource(this,Uri.parse(url),headers);player.setOnPreparedListener(p->{p.start();notice("Playing preview. Use Stop audio to finish.");});player.setOnErrorListener((p,w,e)->{notice("Preview is unavailable. Please try again.");return true;});player.prepareAsync();}catch(Exception e){error("Audio could not start.");}}
    void stopAudio(){if(player!=null){player.release();player=null;}}
    void external(String url){try{Uri uri=Uri.parse(url);if(!MusicNavigation.externalScheme(uri.getScheme()))throw new Exception();startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception e){error("This link cannot be opened.");}}
    void checkout(JSONObject data,JSONObject context){if(!data.optBoolean("requiresPayment",true)){notice("Confirmed by HYMN.");if(context.optString("type").equals("distribution"))distribution.submitWithoutPayment(data,context);else home();return;}try{paymentContext=new JSONObject(context.toString());paymentContext.put("userId",session.optJSONObject("user")==null?0:session.optJSONObject("user").optInt("id"));paymentContext.put("orderId",data.optString("orderId"));paymentContext.put("subscriptionId",data.optString("subscriptionId"));api.save("pending-payment",paymentContext.toString());Checkout checkout=new Checkout();checkout.setKeyID(data.optString("key",data.optString("keyId")));JSONObject options=json("name","HYMN Music","description",context.optString("description","Your music, together."),"currency",data.optString("currency","INR"),"theme",json("color","#202c3b"));if(!data.optString("subscriptionId").isEmpty())options.put("subscription_id",data.getString("subscriptionId"));else{options.put("order_id",data.getString("orderId"));options.put("amount",data.optLong("amountPaise",data.optLong("amount")));}JSONObject user=session.optJSONObject("user");if(user!=null)options.put("prefill",json("name",user.optString("name"),"email",user.optString("email")));checkout.open(this,options);}catch(Exception e){error("Checkout could not open. Your order is saved; do not pay again if your bank shows a charge.");}}
    @Override public void onPaymentSuccess(String id,PaymentData data){try{JSONObject context=new JSONObject(api.saved("pending-payment"));JSONObject proof=json("razorpay_payment_id",id,"razorpay_order_id",data.getOrderId(),"razorpay_signature",data.getSignature());if(!context.optString("subscriptionId").isEmpty())proof.put("razorpay_subscription_id",context.getString("subscriptionId"));context.put("proof",proof);api.save("pending-payment",context.toString());retryPayment();}catch(Exception e){error("Payment returned. Check your order status before trying another payment.");}}
    @Override public void onPaymentError(int code,String message,PaymentData data){notice("Checkout closed. Check your purchases if your bank shows a charge.");}
    void retryPayment(){try{JSONObject context=new JSONObject(api.saved("pending-payment")),proof=context.optJSONObject("proof");if(context.optInt("userId")>0&&(session.optJSONObject("user")==null||context.optInt("userId")!=session.optJSONObject("user").optInt("id"))){error("Sign in to the account that started this payment to confirm it.");return;}if(proof==null){error("No payment confirmation has returned yet. Check your bank and order history before paying again.");return;}String type=context.optString("type");String endpoint=context.optString("endpoint");JSONObject payload=proof;if(type.equals("playlist"))payload=json("action","verify","orderId",proof.optString("razorpay_order_id"),"paymentId",proof.optString("razorpay_payment_id"),"signature",proof.optString("razorpay_signature"));if(type.equals("distribution")){distribution.verifyPayment(context,proof);return;}JSONObject sent=payload;post(endpoint,sent,result->{api.save("pending-payment","");notice("Payment verified by HYMN.");restore();});}catch(Exception e){error("No pending payment was found.");}}
    @Override public void onBackPressed(){if(screen.equals("home")){super.onBackPressed();}else if(screen.equals("release-editor")){distribution.leave();}else home();}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("screen",screen);}
    @Override protected void onDestroy(){stopAudio();workers.shutdownNow();super.onDestroy();}
